window.DEEPDIVE=window.DEEPDIVE||{};window.DEEPDIVE["tree-of-thoughts"]={"title":"思维树 ToT：在多个中间方案间搜索与回溯","subtitle":"理解状态、候选生成、价值评估、BFS/DFS、剪枝和搜索预算，并区分探索空间扩大与答案正确。","thesis":"ToT 把一次线性生成改成显式搜索：从状态扩展多个候选“思路”，由评估器选择、剪枝或回溯；质量来自<b>搜索空间、评估器和预算</b>，弱评估会更昂贵地保留错误路径。","quality":{"contractVersion":2,"examples":[{"section":7,"evidence":{"setup":"初始串值状态 S0、三个原因分支、最多四节点预算","rule":"先比较 A 缺 user_id、B 命名空间、C 对象复用","steps":"A1 复合键通过 4/4 成为终态","interpretation":"说明为何必须剪枝"}}],"formulas":[{"id":"tot-full-tree-nodes","section":7,"formulaIndex":1,"symbols":[{"name":"Nnodes","meaning":"包含根节点在内的完整搜索树节点总数","evidence":"节点总数 Nnodes=121"},{"name":"k","meaning":"每个状态平均扩展出的候选分支数量","evidence":"分支数 k=3"},{"name":"d","meaning":"从根状态向下扩展的最大搜索深度","evidence":"搜索深度 d=4"}]}],"termReviews":[{"section":1,"reviewedAt":"2026-07-27","terms":[{"name":"CoT","meaning":"沿一条生成前缀产生中间推理步骤的思维链方法","purpose":"对比 ToT 保存分支并可回溯的能力","definitionEvidence":"线性 CoT","purposeEvidence":"解决线性 CoT 的路径锁定"}]},{"section":3,"reviewedAt":"2026-07-27","terms":[{"name":"BFS","meaning":"按深度逐层扩展所有候选的广度优先搜索","purpose":"优先覆盖浅层可能解但需要保存更多状态","definitionEvidence":"BFS 先铺同层","purposeEvidence":"输出 BFS、DFS 或 beam 的访问顺序"},{"name":"DFS","meaning":"沿一个分支尽量深入后再回溯的深度优先搜索","purpose":"用较少内存快速找到深解但可能浪费在错误首支","definitionEvidence":"DFS 先深入","purposeEvidence":"输出 BFS、DFS 或 beam 的访问顺序"},{"name":"beam","meaning":"每一层只保留固定数量最高分候选的束搜索","purpose":"在完整广搜成本与单路径深搜之间折中","definitionEvidence":"beam 每层只留 b 个高分状态","purposeEvidence":"候选上限"}]}],"sectionContracts":[{"section":1,"definition":{"answer":"思维树把线性生成改成可保存分支评估剪枝和回溯的搜索。","evidence":"输出带父子关系的搜索树、被保留或剪枝的状态及验证终态"},"problem":{"answer":"它解决早期选择错误后线性前缀难以恢复的问题。","evidence":"解决线性 CoT 的路径锁定"},"inputOutput":{"answer":"输入状态候选评估预算，输出树状态与终态。","evidence":"输入当前问题状态、候选扩展、评估器和预算"},"mechanism":{"answer":"保存备选和父子关系，按评估结果改变展开顺序并回溯。","evidence":"保存备选状态和真正回溯"},"interpretation":{"answer":"真正 ToT 必须有外部搜索控制而非只写更多段落。","evidence":"真正搜索由外部状态控制"},"boundary":{"answer":"没有状态保存和回溯的多段文字不属于 ToT。","evidence":"不算 ToT"}},{"section":2,"definition":{"answer":"搜索问题由状态扩展价值评估和终止条件四部分构成。","evidence":"输出状态表示、扩展操作、价值评估与终止条件"},"problem":{"answer":"它解决什么样的中间思路才能被系统搜索和复用。","evidence":"影响后续决策的事实"},"inputOutput":{"answer":"输入事实产物动作评分终止，输出四项搜索定义。","evidence":"输入任务事实、已验证产物、合法动作、评分维度和完成谓词"},"mechanism":{"answer":"状态保留事实，扩展合法动作，评分候选，外部条件终止。","evidence":"状态只保留影响后续决策的事实"},"interpretation":{"answer":"粒度决定搜索能否去重定位和控制分支。","evidence":"粒度过细会爆炸"},"boundary":{"answer":"过粗状态会掩盖错误并妨碍去重。","evidence":"过粗会掩盖错误并妨碍去重"}},{"section":3,"definition":{"answer":"BFS DFS beam 是有限预算下不同的状态访问策略。","evidence":"输出 BFS、DFS 或 beam 的访问顺序与候选上限"},"problem":{"answer":"它解决有限预算应先铺开还是先深入的问题。","evidence":"BFS 先铺同层，DFS 先深入"},"inputOutput":{"answer":"输入 k d b 内存验证成本，输出策略与上限。","evidence":"输入分支数 k、深度 d、beam 宽度 b、内存和验证成本"},"mechanism":{"answer":"BFS 按层、DFS 沿支、beam 每层保留高分候选。","evidence":"beam 每层只留 b 个高分状态"},"interpretation":{"answer":"完整树随分支和深度指数增长，必须剪枝。","evidence":"完整树节点随 k 和 d 指数增长"},"boundary":{"answer":"搜索评分不能绕过动作权限和真实执行门。","evidence":"不能绕过高风险动作的权限和真实执行门"}},{"section":4,"definition":{"answer":"评估器判断候选状态可行性价值风险和验证成本。","evidence":"输出淘汰、保留、优先级或终态确认"},"problem":{"answer":"它解决模型自评是否足以决定剪掉哪些分支。","evidence":"自评共享生成器盲点"},"inputOutput":{"answer":"输入状态约束证据收益风险成本，输出评估动作。","evidence":"输入候选状态、硬约束、证据、预计收益、风险、剩余成本和真实验证结果"},"mechanism":{"answer":"先强制硬约束，再用证据测试排序软价值。","evidence":"违反权限语法的候选直接淘汰"},"interpretation":{"answer":"分数是成功估计而非真值，需按实际终态校准。","evidence":"不能把一个 0.73 分伪装成真值"},"boundary":{"answer":"可执行任务优先使用外部测试而非同模型自评。","evidence":"优先用测试与规则"}},{"section":5,"definition":{"answer":"搜索预算计入生成评分工具状态和被剪候选的全部成本。","evidence":"输出继续扩展、剪枝、回溯或停止"},"problem":{"answer":"它解决更多分支何时不再值得继续投入。","evidence":"边际成功增益和停止上限"},"inputOutput":{"answer":"输入各类成本边际增益上限，输出搜索动作。","evidence":"输入每次生成评分工具执行 token 与墙钟成本、边际成功增益和停止上限"},"mechanism":{"answer":"持续比较新增候选成功增益与单位成本。","evidence":"记录被剪候选已经消耗的成本"},"interpretation":{"answer":"beam 翻倍仅增一点时应把预算转向验证或状态。","evidence":"应把预算用于验证或初始状态"},"boundary":{"answer":"搜索扩大探索空间但不能保证质量收益。","evidence":"搜索扩大探索空间，不保证收益"}},{"section":6,"definition":{"answer":"ToT 可在文本状态搜索，Agent 还需真实环境反馈和权限。","evidence":"输出仅供规划的候选与可执行的受权动作"},"problem":{"answer":"它解决思维树是否等同真实世界 Agent 规划。","evidence":"Agent 还必须调用工具获得新事实"},"inputOutput":{"answer":"输入想象状态工具观察权限环境，输出规划或动作。","evidence":"输入文本内想象状态、真实工具观察、当前权限和动态环境"},"mechanism":{"answer":"文本候选经工具观察更新，动作再通过授权执行。","evidence":"在环境变化后重规划"},"interpretation":{"answer":"想象出的测试通过不能替代真实业务回执。","evidence":"想象测试通过不能替代实际回执"},"boundary":{"answer":"搜索不能创造上下文中缺失的事实知识。","evidence":"不会创造模型上下文中缺失的知识"}},{"section":7,"definition":{"answer":"缓存案例演示有限预算下分支验证剪枝补丁和回溯。","evidence":"输出搜索轨迹、补丁终态与回溯点"},"problem":{"answer":"它解决三个可能原因如何避免同时乱改。","evidence":"先比较 A 缺 user_id、B 命名空间、C 对象复用"},"inputOutput":{"answer":"输入 S0 分支预算测试，输出轨迹终态回溯。","evidence":"输入初始串值状态 S0、三个原因分支、最多四节点预算和测试证据"},"mechanism":{"answer":"比较三原因，用证据剪 B，扩 A，失败则回 C。","evidence":"测试把 B 剪掉并优先扩展 A"},"interpretation":{"answer":"A1 四项测试通过才成为终态而非只靠高分。","evidence":"A1 复合键通过 4/4 成为终态"},"boundary":{"answer":"完整树一百二十一节点说明有限预算必须剪枝。","evidence":"说明为何必须剪枝"}},{"section":8,"definition":{"answer":"评估器失败分析定位搜索如何系统性淘汰正确路径。","evidence":"输出过早剪枝、评分泄漏、同质分支、模拟当事实或循环回溯的归因"},"problem":{"answer":"它解决弱评估器为何可能比单次生成更危险。","evidence":"评估器失败分析输入"},"inputOutput":{"answer":"输入评分剪枝差异测试历史，输出失败归因。","evidence":"输入各分支评分、被剪顺序、状态差异、真实测试和访问历史"},"mechanism":{"answer":"拆分评分维度，保留探索配额访问集并真实验证终态。","evidence":"拆分硬可行性、证据、收益、风险与成本"},"interpretation":{"answer":"高分仅改变探索优先级，不能替代真实环境成功。","evidence":"终态必须由环境验证"},"boundary":{"answer":"不可逆昂贵执行不适合盲目扩展分支。","evidence":"不适合盲目扩展"}}]},"html":"\n        <div class=\"dd-goals\"><b>读完你应该能：</b>定义状态与 thought；区分 BFS/DFS；设计价值评估；控制分支和停止。</div>\n        \n      <section class=\"dd-sec\" data-section-role=\"core\"><h2><span class=\"dd-n\">1</span>线性路径为什么会卡死<span class=\"dd-badge intuition\">直觉</span></h2><p class=\"dd-lead\">早期一步错了，后面还能靠继续生成修回来吗？</p><p>线性 CoT 常把早期选择当成既定前提，后续 token 只会在这个前缀条件下继续。ToT 把中间结果外化为多个候选状态，允许发现死路后回到最近分叉点，适合规划、谜题、程序修复和组合搜索。</p><p>关键差异不是“写得更长”，而是系统保存未选择候选和父子关系，并能调用评估器改变展开顺序。若所有候选仍被拼成一段文本后一次生成，就没有真正的回溯控制。</p><p>思维树输入当前问题状态、候选扩展、评估器和预算，输出带父子关系的搜索树、被保留或剪枝的状态及验证终态。它让系统在早期选择错误后回到分叉点，而不是沿同一前缀继续生成；解决线性 CoT 的路径锁定。若没有保存备选状态和真正回溯，只是写多段文字，不算 ToT。这表示真正搜索由外部状态控制，而不是由生成文字长度决定。</p></section>\n      <section class=\"dd-sec\" data-section-role=\"core\"><h2><span class=\"dd-n\">2</span>搜索问题的四要素<span class=\"dd-badge eng\">建模</span></h2><p class=\"dd-lead\">什么才算一个可搜索的“思路”？</p><p>需定义状态表示、扩展操作、价值/可行性评分和终止条件。状态只包含影响后续决策的事实与产物；扩展是合法动作或原因假设；评分估计可行性、收益、风险和剩余成本；终止由外部完成谓词决定。粒度太细会分支爆炸，太粗又无法定位错误或复用相同子状态。</p><p>缓存案例的状态不是一段“我认为可能是缓存问题”的散文，而是已运行测试、当前代码 diff、仍存活的原因假设与预算。这样的状态才能哈希去重、回放和交给独立验证器。</p><p>搜索建模输入任务事实、已验证产物、合法动作、评分维度和完成谓词，输出状态表示、扩展操作、价值评估与终止条件。状态只保留影响后续决策的事实，扩展产生可执行候选，评分区分硬可行性与软价值，终态由外部条件确认。粒度过细会爆炸，过粗会掩盖错误并妨碍去重。</p></section>\n      <section class=\"dd-sec\" data-section-role=\"core\"><h2><span class=\"dd-n\">3</span>BFS、DFS 与 beam<span class=\"dd-badge math\">搜索</span></h2><p class=\"dd-lead\">有限预算下先走深还是先铺开？</p><p>BFS 先覆盖同层，适合浅解但需保存大量状态；DFS 内存小、能快速得到一个深解，却容易把预算耗在错误首分支；beam 每层只留 b 个高分候选，是质量与成本折中。分支 k、深度 d 的叶子为 kᵈ，总节点为 <code>(k^(d+1)-1)/(k-1)</code>，必须剪枝。</p><p>策略应匹配验证成本：便宜规则可广搜，昂贵真实执行宜先用静态证据筛选；高风险动作不能因为某分支分数高就直接执行，还需权限门。</p><p>搜索策略输入分支数 k、深度 d、beam 宽度 b、内存和验证成本，输出 BFS、DFS 或 beam 的访问顺序与候选上限。BFS 先铺同层，DFS 先深入，beam 每层只留 b 个高分状态；完整树节点随 k 和 d 指数增长。策略分数不能绕过高风险动作的权限和真实执行门。</p></section>\n      <section class=\"dd-sec\" data-section-role=\"core\"><h2><span class=\"dd-n\">4</span>评估器决定剪谁<span class=\"dd-badge intuition\">验证</span></h2><p class=\"dd-lead\">模型给自己打分可靠吗？</p><p>可用规则、环境执行、独立模型或多次投票。自评会有自信偏差和共享盲点；可验证任务应优先使用确定性检查。评分还要区分硬约束与软价值：违反权限或语法的状态直接淘汰，尚未验证但有潜力的状态保留不确定性，不能把二者压成一个看似精确的 0.73。</p><p>评估器本身需要校准：按分数区间统计实际终态成功率，并检查它是否系统偏好更长文本、熟悉措辞或某个生成位置。</p><p>评估器输入候选状态、硬约束、证据、预计收益、风险、剩余成本和真实验证结果，输出淘汰、保留、优先级或终态确认。违反权限语法的候选直接淘汰，证据不足但有潜力的状态保留不确定性，可执行任务优先用测试与规则。自评共享生成器盲点，不能把一个 0.73 分伪装成真值。</p></section>\n      <section class=\"dd-sec\" data-section-role=\"core\"><h2><span class=\"dd-n\">5</span>搜索会放大成本<span class=\"dd-badge eng\">预算</span></h2><p class=\"dd-lead\">更多分支何时不再值得？</p><p>记录每次扩展、评分、工具执行和 token；按价值差、无进展、深度或总预算停止。先用路由器只在困难切片启用，简单任务仍直接生成。搜索成本不只来自叶子：被剪掉的候选也已消耗生成与评分，状态序列化和真实工具调用还会增加墙钟延迟。</p><p>可比较“每新增一个候选带来的成功率增益”与单位成本；若 beam 从 2 增至 4 只提升 1 个百分点却翻倍调用，应把预算转给验证器或更好的初始状态。</p><p>预算控制输入每次生成评分工具执行 token 与墙钟成本、边际成功增益和停止上限，输出继续扩展、剪枝、回溯或停止。记录被剪候选已经消耗的成本，只在困难切片启用搜索；若 beam 从 2 到 4 只提升一点却翻倍调用，应把预算用于验证或初始状态。搜索扩大探索空间，不保证收益。</p></section>\n      <section class=\"dd-sec\" data-section-role=\"core\"><h2><span class=\"dd-n\">6</span>与 Agent 规划的关系<span class=\"dd-badge intuition\">边界</span></h2><p class=\"dd-lead\">ToT 是否等于真实世界 Agent？</p><p>ToT 可只在文本状态中搜索；Agent 规划还需工具反馈、权限和动态环境。想象出的状态不能替代真实执行观察。</p><div class=\"dd-note warn\"><b>搜索不会创造缺失知识。</b>　所有分支共享模型与上下文边界。</div><p>Agent 边界输入文本内想象状态、真实工具观察、当前权限和动态环境，输出仅供规划的候选与可执行的受权动作。ToT 可以只搜索文字，Agent 还必须调用工具获得新事实并在环境变化后重规划；想象测试通过不能替代实际回执。搜索也不会创造模型上下文中缺失的知识。</p></section>\n      <section class=\"dd-sec\" data-section-role=\"core\"><h2><span class=\"dd-n\">7</span>一次缓存修复怎样展开搜索树<span class=\"dd-badge math\">运行示例</span></h2><p class=\"dd-lead\">当“串值”可能来自缓存键、命名空间或序列化时，怎样在有限预算内探索而不同时乱改三处？</p><figure class=\"dd-fig\"><svg viewBox=\"0 0 680 280\" role=\"img\" aria-label=\"缓存隔离故障的三分支思维树经过测试评分、剪枝与回溯\"><defs><marker id=\"tt1\" markerWidth=\"8\" markerHeight=\"8\" refX=\"6\" refY=\"3\" orient=\"auto\"><path d=\"M0,0 L6,3 L0,6 z\" fill=\"#6b7484\"/></marker></defs><rect x=\"266\" y=\"18\" width=\"148\" height=\"54\" rx=\"8\" fill=\"#21252d\" stroke=\"#6b8cbe\"/><text x=\"340\" y=\"40\" text-anchor=\"middle\" class=\"svg-t\">状态 S0：跨用户串值</text><text x=\"340\" y=\"59\" text-anchor=\"middle\" class=\"svg-t\" font-size=\"10\">预算：最多验证 4 个节点</text><path d=\"M300,72 L132,116\" stroke=\"#6b7484\" marker-end=\"url(#tt1)\"/><path d=\"M340,72 L340,116\" stroke=\"#6b7484\" marker-end=\"url(#tt1)\"/><path d=\"M380,72 L548,116\" stroke=\"#6b7484\" marker-end=\"url(#tt1)\"/><rect x=\"44\" y=\"118\" width=\"176\" height=\"72\" rx=\"8\" fill=\"#21252d\" stroke=\"#4f9d78\"/><text x=\"132\" y=\"141\" text-anchor=\"middle\" class=\"svg-t\">A：key 缺 user_id</text><text x=\"132\" y=\"161\" text-anchor=\"middle\" class=\"svg-t\" font-size=\"10\">读代码 + 成对测试：2/2 支持</text><text x=\"132\" y=\"179\" text-anchor=\"middle\" class=\"svg-t\" font-size=\"10\">价值 0.90，继续扩展</text><rect x=\"252\" y=\"118\" width=\"176\" height=\"72\" rx=\"8\" fill=\"#21252d\" stroke=\"#c77b72\"/><text x=\"340\" y=\"141\" text-anchor=\"middle\" class=\"svg-t\">B：共享命名空间错误</text><text x=\"340\" y=\"161\" text-anchor=\"middle\" class=\"svg-t\" font-size=\"10\">配置检查：租户空间已分离</text><text x=\"340\" y=\"179\" text-anchor=\"middle\" class=\"svg-t\" font-size=\"10\">价值 0.10，剪枝</text><rect x=\"460\" y=\"118\" width=\"176\" height=\"72\" rx=\"8\" fill=\"#21252d\" stroke=\"#d3a05a\"/><text x=\"548\" y=\"141\" text-anchor=\"middle\" class=\"svg-t\">C：序列化复用对象</text><text x=\"548\" y=\"161\" text-anchor=\"middle\" class=\"svg-t\" font-size=\"10\">尚无证据，验证成本高</text><text x=\"548\" y=\"179\" text-anchor=\"middle\" class=\"svg-t\" font-size=\"10\">价值 0.45，候补</text><path d=\"M132,190 L132,220\" stroke=\"#6b7484\" marker-end=\"url(#tt1)\"/><rect x=\"38\" y=\"222\" width=\"188\" height=\"48\" rx=\"8\" fill=\"#21252d\" stroke=\"#4f9d78\"/><text x=\"132\" y=\"242\" text-anchor=\"middle\" class=\"svg-t\">A1：复合键补丁</text><text x=\"132\" y=\"259\" text-anchor=\"middle\" class=\"svg-t\" font-size=\"10\">隔离/命中测试 4/4 → 终态</text><path d=\"M226,246 C335,270 493,259 520,192\" fill=\"none\" stroke=\"#6b7484\" stroke-dasharray=\"4 3\" marker-end=\"url(#tt1)\"/><text x=\"374\" y=\"252\" text-anchor=\"middle\" class=\"svg-t\" font-size=\"10\">若 A1 失败，回溯到 C，而非沿 A 继续编故事</text></svg><figcaption>图 1　“思路”被表示成原因假设与可执行验证；确定性测试更新状态价值，剪枝依据证据而非文字听起来是否合理。</figcaption></figure><div class=\"dd-table-wrap\"><table class=\"dd-table\"><thead><tr><th>策略</th><th>最多访问节点</th><th>本例轨迹</th><th>特点</th></tr></thead><tbody><tr><td>DFS</td><td>4</td><td>S0→A→A1</td><td>快速深入；若首分支错会浪费深度</td></tr><tr><td>BFS</td><td>4</td><td>S0→A,B,C</td><td>先比较原因，但预算不足以验证补丁</td></tr><tr><td>beam=2</td><td>4</td><td>保留 A,C→扩展 A1</td><td>兼顾备选与深度，依赖评分质量</td></tr></tbody></table></div><p>若分支数 <code>k=3</code>、深度 <code>d=4</code>，完整树节点数为 <code>1+3+9+27+81=121</code>，不是只算叶子的 81。每节点若需 800 token，完整搜索约 96,800 token；beam=2 每层最多保留并扩展两个状态，粗略上限降到 <code>1+4×(2×3)=25</code> 个候选评估，仍需为真实工具执行单独计费。</p><div class=\"dd-note key\"><b>状态去重：</b>两个文本分支若都得到相同代码 diff 与测试结果，应合并为同一状态；否则同义改写会伪造搜索多样性并重复花费预算。</div><p>缓存案例输入初始串值状态 S0、三个原因分支、最多四节点预算和测试证据，输出搜索轨迹、补丁终态与回溯点。先比较 A 缺 user_id、B 命名空间、C 对象复用，测试把 B 剪掉并优先扩展 A；A1 复合键通过 4/4 成为终态，失败则回溯 C。完整分支数 k=3、搜索深度 d=4 的节点总数 Nnodes=121，说明为何必须剪枝。</p><div class=\"dd-formula\"><math display=\"block\" aria-label=\"完整 k 叉树的节点总数\"><mi>Nnodes</mi><mo>=</mo><mfrac><mrow><msup><mi>k</mi><mrow><mi>d</mi><mo>+</mo><mn>1</mn></mrow></msup><mo>−</mo><mn>1</mn></mrow><mrow><mi>k</mi><mo>−</mo><mn>1</mn></mrow></mfrac></math></div></section>\n      <section class=\"dd-sec\" data-section-role=\"core\"><h2><span class=\"dd-n\">8</span>评估器错误会怎样放大<span class=\"dd-badge eng\">失败边界</span></h2><p class=\"dd-lead\">搜索扩大候选空间后，为什么弱评估器可能比单次生成更危险？</p><p>生成器负责提出可能性，评估器决定计算预算流向哪里。若评估器偏爱详细措辞、短补丁或与自己观点相似的分支，beam 会在每层系统性淘汰真正解。应把评分拆为硬可行性、证据支持、预计收益、风险与验证成本；能运行测试时优先使用测试，不能验证时保留不确定性而非伪造精确分数。</p><div class=\"dd-table-wrap\"><table class=\"dd-table\"><thead><tr><th>失败</th><th>表现</th><th>缓解</th></tr></thead><tbody><tr><td>过早剪枝</td><td>正确分支初期证据少被淘汰</td><td>保留探索配额或不确定性上界</td></tr><tr><td>评分泄漏</td><td>评估器看到参考答案措辞</td><td>隔离数据与隐藏验证</td></tr><tr><td>分支同质化</td><td>多个候选只是同义改写</td><td>按状态/动作差异去重</td></tr><tr><td>模拟当事实</td><td>想象测试通过就标记终态</td><td>终态必须经真实环境验证</td></tr><tr><td>循环回溯</td><td>在两个状态间反复切换</td><td>访问集、深度、预算和无进展终止</td></tr></tbody></table></div><div class=\"dd-note warn\"><b>失败边界：</b>ToT 不适合每个任务。答案一步可验证、动作空间固定可用传统算法、或每次真实执行不可逆且昂贵时，盲目扩展分支只会增加成本和风险。</div><p>评估器失败分析输入各分支评分、被剪顺序、状态差异、真实测试和访问历史，输出过早剪枝、评分泄漏、同质分支、模拟当事实或循环回溯的归因。拆分硬可行性、证据、收益、风险与成本，并保留探索配额和访问集；终态必须由环境验证。真实执行不可逆且昂贵时不适合盲目扩展。</p></section>\n      <section class=\"dd-sec\" data-section-role=\"reference\"><h2><span class=\"dd-n\">9</span>常见误区与学习路线<span class=\"dd-badge intuition\">误区与路线</span></h2><p class=\"dd-lead\">思维树是显式候选搜索框架，不是让模型输出更多段落的格式技巧。</p><div class=\"dd-table-wrap\"><table class=\"dd-table\"><thead><tr><th>常见误解</th><th>更准确的理解</th></tr></thead><tbody><tr><td>生成三条回答就是 ToT</td><td>还需状态、扩展、评估、剪枝、回溯和终止</td></tr><tr><td>分支越多越可能正确</td><td>节点指数增长，弱评估器会把预算导向错误路径</td></tr><tr><td>模型自评足以选择分支</td><td>自评共享盲点；可验证任务优先使用规则或环境反馈</td></tr><tr><td>高分状态就是已完成</td><td>文本评分是估计，终态必须满足外部完成谓词</td></tr><tr><td>ToT 等于 Agent 规划</td><td>Agent 还需真实工具状态、权限、动态重规划与副作用控制</td></tr></tbody></table></div><div class=\"dd-table-wrap\"><table class=\"dd-table\"><thead><tr><th>层级</th><th>概念依赖与延伸</th></tr></thead><tbody><tr><td>先修</td><td>思维链、搜索、概率采样、评测</td></tr><tr><td><b>本页核心</b></td><td>状态、候选扩展、价值评估、BFS/DFS/beam、剪枝与回溯</td></tr><tr><td>紧邻</td><td>自一致性、智能体规划、反思、测试时计算</td></tr><tr><td>工程延伸</td><td>代码执行、ReAct、多智能体、可观测性和预算路由</td></tr></tbody></table></div><p>误区辨析输入“生成多条就是 ToT、分支越多越好、自评足够、高分即完成、ToT 等于 Agent”等主张，输出缺失的状态、评估、剪枝、回溯、终止、环境和权限条件。逐项映射到可观察证据和失败模式。该表用于纠正概念，不代替具体搜索策略的质量成本评测。</p></section>\n        <section class=\"dd-sec\" data-section-role=\"synthesis\"><h2><span class=\"dd-n\">10</span>把因果链连起来<span class=\"dd-badge intuition\">综合</span></h2><p class=\"dd-lead\">这个概念怎样从问题一路连接到可验证的实践？</p><ol class=\"dd-chain\"><li>把问题表示为状态</li><li>生成多个候选扩展</li><li>评估可行性与价值</li><li>按 BFS/DFS/beam 保留</li><li>失败回溯或继续扩展</li><li>验证终态并比较搜索成本</li></ol></section>\n        <section class=\"dd-sec\" data-section-role=\"assessment\"><h2><span class=\"dd-n\">11</span>误区与自测<span class=\"dd-badge intuition\">自测</span></h2><p class=\"dd-lead\">你能否不用背术语，解释它的机制、边界与验证方法？</p><div class=\"dd-quiz\"><ol><li>ToT 比 CoT 多什么？</li><li>完整树为何昂贵？</li><li>beam search 做什么？</li><li>自评主要风险？</li><li>想象状态能替代工具结果吗？</li><li>假设“思维树 ToT：在多个中间方案间搜索与回溯”在离线示例上表现正常、上线后核心结果却下降，你会怎样按输入、内部变换、输出反馈和适用边界定位问题？</li><li>如何为“思维树 ToT：在多个中间方案间搜索与回溯”设计一个最小对照实验，证明观察到的改善来自核心机制，而不是数据、提示、权限或评测口径同时变化？</li><li>为什么不能只用一个平均分判断“思维树 ToT：在多个中间方案间搜索与回溯”已经可靠？应怎样按场景切片并设置失败边界？</li></ol></div><details class=\"dd-answers\"><summary>参考答案</summary><ol><li>显式分支、评分、剪枝和回溯。</li><li>节点随分支和深度指数增长。</li><li>每层只保留固定数量高分候选。</li><li>与生成器共享偏差和盲点。</li><li>不能。</li><li>先保存同一失败样本及环境，确认输入、权限和前置条件没有漂移；再记录关键中间状态，检查机制是否按本页描述完成变换；随后把原始输出与独立指标、人工终验对照；最后用边界样例和对照实验复测。只有定位到首次偏离预期的环节，才能判断应修改数据、机制、评测还是使用边界。</li><li>固定数据、模型版本、提示、权限、预算和评测，只改变一个与核心机制直接相关的因素，并在多个样本与随机种子上重复；同时保存中间状态和失败样本。若差异只在目标因素变化时稳定出现，才支持机制解释，否则应继续排查混杂变量。</li><li>平均分会隐藏少数类别、极端输入、成本、延迟和安全失败。至少按难度、输入类型、长度或规模、风险等级及已知边界切片，同时报告质量、资源和失败率；高风险硬约束不能被其他切片的高分抵消。</li></ol></details></section>\n        <div class=\"dd-src\"><b>资料来源与改编说明</b><ul><li><a href=\"https://arxiv.org/abs/2305.10601\" target=\"_blank\" rel=\"noopener\">Tree of Thoughts</a>：显式思维搜索</li><li><a href=\"https://arxiv.org/abs/2308.09687\" target=\"_blank\" rel=\"noopener\">Graph of Thoughts</a>：图结构推理</li><li><a href=\"https://arxiv.org/abs/2310.04406\" target=\"_blank\" rel=\"noopener\">Language Agent Tree Search</a>：搜索与环境反馈</li></ul><div class=\"dd-src-date\">访问日期：2026-07-22</div></div>"};
